assert len(P) == 20, len(P)
out = []
for cid, v in P.items():
    obj = {"case_id": cid, "prediction_text": v["prediction_text"], "basis": v["basis"], "confidence": v["confidence"], "trigger": v["trigger"]}
    path = os.path.join(BASE, cid + ".json")
    with open(path, "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
    # per-case assert: reopen exactly this file and verify
    with open(path, encoding="utf-8") as f:
        back = json.load(f)
    assert back["case_id"] == cid and set(back) == {"case_id","prediction_text","basis","confidence","trigger"}
    assert set(back["trigger"]) == {"changed_main","reserve_used","disputed","reason"}
    out.append((cid, os.path.getsize(path)))
for cid, sz in out:
    print(cid, sz)
print("TOTAL", len(out))
